describe('EditablePhoneComponent numbers', () => {
  let component: EditablePhoneComponent;
  let changes: (string | null)[];

  const create = (inputs: Record<string, unknown> = {}) => {
    TestBed.configureTestingModule({
      imports: [EditablePhoneComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
    const fixture = TestBed.createComponent(EditablePhoneComponent);
    Object.entries(inputs).forEach(([name, value]) => fixture.componentRef.setInput(name, value));
    component = fixture.componentInstance;
    changes = [];
    component.registerOnChange((value: string | null) => changes.push(value));
    fixture.detectChanges();
  };

  afterEach(() => TestBed.resetTestingModule());

  it('starts with the default country', () => {
    create({ defaultCountry: 'FR' });

    expect(component.selectedCountry().code).toBe('FR');
    expect(component.dialCode.value).toBe('+33');
  });

  it('falls back to the first country with an unknown default', () => {
    create({ defaultCountry: 'XX' });

    expect(component.selectedCountry()).toBeTruthy();
  });

  it('emits the number in E.164 with the dial code', () => {
    create();

    component.localNumber.setValue('612 34 56 78');
    expect(changes.at(-1)).toBe('+34612345678');

    component.selectCountry(component.filteredCountries().find((c) => c.code === 'US')!);
    expect(changes.at(-1)).toBe('+1612345678');
    expect(component.countrySearch()).toBe('');

    component.localNumber.setValue('');
    expect(changes.at(-1)).toBeNull();
  });

  it('puts the preferred countries first and filters by name or dial code', () => {
    create({ preferredCountries: ['GB'] });

    expect(component.filteredCountries()[0].code).toBe('GB');
    component.countrySearch.set('+351');
    expect(component.filteredCountries().map((c) => c.code)).toContain('PT');
  });

  it('splits a number set from outside into country and local number', () => {
    create();

    (component as any).control.setValue('+33612345678');

    expect(component.selectedCountry().code).toBe('FR');
    expect(component.localNumber.value).toBe('612345678');
  });

  it('ignores an empty or unreadable number set from outside', () => {
    create();

    (component as any).control.setValue('');
    (component as any).control.setValue('not a phone');

    expect(component.selectedCountry().code).toBe('ES');
  });

  it('does not validate a number that is only the dial code', () => {
    create();

    expect(component.validate(null)).toBeNull();
  });
});
